#include "appimages_wrap.h"
#include <lua.h>
#include <lauxlib.h>
#include <iup.h>
#include <iuplua.h>
#include <string.h>

/* Generated by scripts/embed_images.py at build time. Defines
 * lunar_embedded_images[] -- {name, width, height, rgba} terminated by a NULL
 * name. */
#include "embedded_images.h"

/*** Bitmaps compiled into the executable.
 *
 * The app needs exactly two bitmaps before any file I/O is meaningful: the
 * statusbar logo and the window icon. Loading them from disk with
 * `iup.LoadImage` was the only thing pulling the IM imaging library into the
 * binary -- roughly a megabyte of TIFF/EXIF/JPEG/colour-space machinery plus a
 * static libstdc++ -- for 3364 pixels. The pixels are now decoded at build time
 * (see scripts/embed_images.py) and wrapped here with `IupImageRGBA`.
 *
 * A side benefit: these can no longer go missing or be corrupted by a partial
 * install, so the statusbar and window icon always render.
 *
 * @module appimages
 */

/*** Look up a bitmap compiled into the executable.
 *
 * @function load
 * @tparam  string  name  Image name, e.g. `"lunar_icon_32"`.
 * @treturn ihandle       Ready-to-use IUP image handle on success.
 * @treturn nil           `nil` if no such image, or if IUP rejected the pixels.
 * @treturn string        Error message on failure.
 * @usage
 *   local appimages = require("appimages")
 *   local icon = appimages.load("lunar_icon_32")
 */
static int l_load(lua_State *L)
{
    const char *name = luaL_checkstring(L, 1);

    for (const LunarEmbeddedImage *e = lunar_embedded_images; e->name; ++e) {
        if (strcmp(e->name, name) != 0) continue;

        Ihandle *img = IupImageRGBA(e->width, e->height, e->rgba);
        if (!img) {
            lua_pushnil(L);
            lua_pushfstring(L, "IupImageRGBA failed for embedded image '%s'", name);
            return 2;
        }
        iuplua_pushihandle(L, img);
        return 1;
    }

    lua_pushnil(L);
    lua_pushfstring(L, "no embedded image named '%s'", name);
    return 2;
}

/*** List the names of every bitmap compiled into the executable.
 *
 * @function names
 * @treturn {string,...}  Array of image names, in declaration order.
 */
static int l_names(lua_State *L)
{
    lua_newtable(L);
    int i = 1;
    for (const LunarEmbeddedImage *e = lunar_embedded_images; e->name; ++e, ++i) {
        lua_pushstring(L, e->name);
        lua_rawseti(L, -2, i);
    }
    return 1;
}

static const luaL_Reg appimages_lib[] = {
    { "load",  l_load  },
    { "names", l_names },
    { NULL,    NULL    }
};

int luaopen_appimages(lua_State *L)
{
    luaL_newlib(L, appimages_lib);
    return 1;
}
